package input

import "time"

// ActionType represents an input action performed by the user on a physical or virtual keypad.
type ActionType string

const (
	ActionDigit     ActionType = "DIGIT"
	ActionBackspace ActionType = "BACKSPACE"
	ActionClear     ActionType = "CLEAR"
	ActionSubmit    ActionType = "SUBMIT"
	ActionCancel    ActionType = "CANCEL"
)

// Event models a discrete input event generated by an input source.
type Event struct {
	Type      ActionType
	Digit     rune
	Timestamp time.Time
}

// Source represents an abstraction over hardware input devices (e.g. numeric keypad,
// touchscreen buttons, standard input, or simulated test injectors).
type Source interface {
	// Events returns a read-only channel delivering input events.
	Events() <-chan Event
	// Close releases any system or device resources held by the source.
	Close() error
}

